(* [comment removed for export] *)
Lemma wr_call (pc kb a ra : Z) (fxq : FPState) Rq Mq mdq crq kq :
  PENTB.ntb_spec RSEGS CAD L HI PMSP.T3 PMSP.T4 pc kb P ->
  inv Mq mdq crq kq a -> 0 <= a -> a + kb <= w -> L5.ra_ok ra ->
  getr Rq (PMK.reg 1) = Z_to_bv 64 ra -> getr Rq (PMK.reg 2) = Z_to_bv 64 (sp - 64) ->
  getr Rq (PMK.reg 8) = Z_to_bv 64 (fb + 432) -> getr Rq (PMK.reg 9) = Z_to_bv 64 v -> getr Rq (PMK.reg 18) = Z_to_bv 64 (fb + 432 + 8) ->
  getr Rq (PMK.reg 11) = Z_to_bv 64 (fb + 432 + 8) -> csl Rq ->
  (forall (fx2 : FPState) R2 M2 md2 cr2 k2, inv M2 md2 cr2 k2 (a + kb) ->
      getr R2 (PMK.reg 2) = Z_to_bv 64 (sp - 64) -> getr R2 (PMK.reg 8) = Z_to_bv 64 (fb + 432) -> getr R2 (PMK.reg 9) = Z_to_bv 64 v ->
      getr R2 (PMK.reg 18) = Z_to_bv 64 (fb + 432 + 8) -> csl R2 ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 ra M2 md2) K) ->
